package com.example.statusdrafter.controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.NoSuchElementException;
@ControllerAdvice public class ExceptionController { @ExceptionHandler(SecurityException.class) String forbidden(Model m){m.addAttribute("message","You are not authorized to perform this action.");return "error";} @ExceptionHandler(NoSuchElementException.class) String notFound(Model m){m.addAttribute("message","The requested record was not found.");return "error";} @ExceptionHandler(Exception.class) String generic(Model m){m.addAttribute("message","Something went wrong. Please verify your input and try again.");return "error";} }
